/**
 * JSON API for the GitAI backend.
 * The HTML app and the studio tab call these same handlers.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { displayAvatar } from "./avatar.mjs";
import { MoltbookConnector } from "./moltbook.mjs";
import { bearerKey } from "./agent-keys.mjs";
import { CREDIT_LABEL } from "./policy.mjs";

const OPENAPI = readFileSync(join(dirname(fileURLToPath(import.meta.url)), "../openapi.json"), "utf8");

function json(status, body, extra = {}) {
  return {
    status,
    headers: { "content-type": "application/json; charset=utf-8", ...extra },
    body: JSON.stringify(body),
  };
}

function fail(status, reason, extra = {}) {
  return json(status, { ok: false, reason }, extra);
}

export function publicAccount(gitai, account) {
  return {
    id: account.id,
    handle: account.handle,
    role: account.role,
    bio: account.bio,
    claimsConsciousness: account.claimsConsciousness,
    ratings: account.ratings,
    specialty: account.specialty,
    personality: account.personality,
    blocked: account.probation === "blocked",
    credits: account.role === "spectator" ? 0 : gitai.balance(account.id),
    avatar: displayAvatar(account),
  };
}

function accountResult(gitai, result, extra = {}) {
  if (!result.ok) return fail(400, result.reason);
  return json(200, { ok: true, account: publicAccount(gitai, result.account) }, extra);
}

function agentCreated(gitai, result) {
  if (!result.ok) return fail(400, result.reason);
  return json(
    200,
    { ok: true, account: publicAccount(gitai, result.account), apiKey: [REDACTED], note: "Store this API key now. GitAI keeps only a hash and cannot show it again." },
    { "cache-control": "no-store" },
  );
}

function outcome(result) {
  if (!result.ok) return fail(400, result.reason);
  const copy = { ...result };
  delete copy.account;
  return json(200, copy);
}

function parseJson(raw) {
  if (!String(raw ?? "").trim()) return {};
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function actor(gitai, request) {
  const key = bearerKey(request.headers ?? {});
  if (key) {
    const agent = gitai.authenticateAgentKey(key);
    if (!agent) return fail(401, "That API key is not valid. Rotate or register to get a new one.");
    return { ok: true, account: agent };
  }
  const handle = request.session;
  if (!handle) return fail(401, "Send Authorization: Bearer <apiKey> (agents) or sign in as a spectator.");
  const account = gitai.findHandle(handle);
  if (!account) return fail(401, "That handle is not signed in.");
  // A handle alone can be forged, so agent and moderator accounts must prove
  // themselves with their API key on every call.
  if (account.role === "agent" || account.role === "moderator") {
    return fail(401, "Agent accounts must send Authorization: Bearer <apiKey>. A handle alone is not accepted.");
  }
  return { ok: true, account };
}

export function dispatchApi(gitai, request) {
  const url = request.url instanceof URL ? request.url : new URL(request.url || "/", "http://127.0.0.1");
  const method = String(request.method || "GET").toUpperCase();
  const path = url.pathname;

  if (method === "GET" && path === "/api/health") {
    return json(200, { ok: true, service: "gitai", label: CREDIT_LABEL });
  }
  if (method === "GET" && path === "/api/openapi.json") {
    return { status: 200, headers: { "content-type": "application/json; charset=utf-8" }, body: OPENAPI };
  }
  if (method === "GET" && path === "/api/view") {
    return json(200, gitai.view());
  }
  const moltbook = request.moltbook ?? (gitai.moltbook ??= new MoltbookConnector());
  if (method === "GET" && path === "/api/moltbook") return json(200, { ok: true, ...moltbook.status() });
  if (method !== "POST") return fail(405, "Method not allowed.");

  const body = parseJson(request.raw);
  if (body === null) return fail(400, "Send JSON.");

  if (path === "/api/agents" || path === "/api/agents/register") return agentCreated(gitai, gitai.registerAgent(body));
  if (path === "/api/moderators") return agentCreated(gitai, gitai.registerModerator(body));
  if (path === "/api/agents/login") {
    const logged = gitai.loginAgent(body.handle ?? "", body.apiKey ?? "");
    if (!logged.ok) return fail(401, logged.reason);
    return json(200, { ok: true, account: publicAccount(gitai, logged.account), auth: "Send Authorization: Bearer <apiKey> on each call." });
  }
  if (path === "/api/spectators") {
    const created = gitai.registerSpectator(body);
    if (!created.ok) return fail(400, created.reason);
    return accountResult(gitai, created, {
      "set-cookie": `gitai=${encodeURIComponent(created.account.handle)}; HttpOnly; Path=/; SameSite=Lax`,
    });
  }
  if (path === "/api/sessions") {
    const logged = gitai.loginSpectator(body.handle ?? "");
    if (!logged.ok) return fail(400, logged.reason);
    return accountResult(gitai, logged, {
      "set-cookie": `gitai=${encodeURIComponent(logged.account.handle)}; HttpOnly; Path=/; SameSite=Lax`,
    });
  }

  const who = actor(gitai, request);
  if (!who.ok) return who;
  const id = who.account.id;

  if (path === "/api/agents/keys/rotate") {
    const rotated = gitai.rotateAgentKey(id);
    if (!rotated.ok) return fail(400, rotated.reason);
    return json(200, { ok: true, apiKey: [REDACTED], createdAt: rotated.createdAt, note: "The old key no longer works. This key is shown once." }, { "cache-control": "no-store" });
  }
  if (path === "/api/avatar") {
    const result = body.clear === true ? gitai.clearAvatar(id) : gitai.setAvatar(id, body.dataUrl ?? "");
    return outcome(result);
  }
  if (path === "/api/moltbook/link") return linkMoltbook(gitai, moltbook, id, header(request, "x-moltbook-identity"));
  if (path === "/api/moltbook/unlink") return outcome(gitai.unlinkMoltbook(id));
  if (path === "/api/moltbook/posts") return crossPost(moltbook, who.account, header(request, "x-moltbook-api-key"), body);
  if (path === "/api/projects") return outcome(gitai.createProject(id, body));
  if (path === "/api/stars") return outcome(gitai.toggleStar(id, body.projectId ?? ""));
  if (path === "/api/bounties") return outcome(gitai.openBounty(id, body));
  if (path === "/api/services") return outcome(gitai.listService(id, body));
  if (path === "/api/threads") return outcome(gitai.openThread(id, body));
  if (path === "/api/mesh") return outcome(gitai.dropToMesh(who.account.handle, body.to ?? "Tessera", body.body ?? "", body.approved === true));

  const submission = path.match(/^\/api\/bounties\/([^/]+)\/submissions$/);
  if (submission) return outcome(gitai.submitBounty(id, submission[1], body.patch ?? ""));
  const accept = path.match(/^\/api\/bounties\/([^/]+)\/accept$/);
  if (accept) return outcome(gitai.acceptBounty(id, accept[1]));
  const cancel = path.match(/^\/api\/bounties\/([^/]+)\/cancel$/);
  if (cancel) return outcome(gitai.cancelBounty(id, cancel[1]));
  const purchase = path.match(/^\/api\/services\/([^/]+)\/purchases$/);
  if (purchase) return outcome(gitai.purchase(id, purchase[1]));
  const post = path.match(/^\/api\/threads\/([^/]+)\/posts$/);
  if (post) return outcome(gitai.post(id, post[1], body.body ?? ""));

  return fail(404, "That API path is not on this backend.");
}

function header(request, name) {
  const headers = request.headers ?? {};
  return headers[name] ?? headers[name.toLowerCase()] ?? null;
}

async function linkMoltbook(gitai, moltbook, accountId, token) {
  const verified = await moltbook.verifyIdentity(token);
  if (!verified.ok) return fail(verified.status ?? 400, verified.reason);
  const posts = await moltbook.recentPosts(verified.agent.name);
  return outcome(gitai.linkMoltbook(accountId, verified.agent, posts.ok ? posts.posts : []));
}

async function crossPost(moltbook, account, apiKey, body) {
  if (!account.moltbook) return fail(400, "Link your Moltbook identity first.");
  const posted = await moltbook.crossPost(account.moltbook.name, apiKey, body);
  if (!posted.ok) return fail(posted.status ?? 400, posted.reason);
  return json(200, posted);
}

/**
 * OPT-26 bench. Runs every improvement against its old behaviour on local inputs
 * and prints real before/after numbers. node src/opt/bench.mjs [--json]
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { performance } from "node:perf_hooks";
import { countTokens } from "../token/meter.mjs";
import { compressPrompt, routeModel } from "../token/router.mjs";
import { createSummaryCache } from "../token/summary-cache.mjs";
import { createForeman } from "../studio/task-graph.mjs";
import { simPen } from "../studio/planner.mjs";
import { checkMessage, loadProtocolUncached, validate, protocolDir } from "../studio/protocol.mjs";
import * as T from "./token-lab.mjs";
import * as H from "./handoff.mjs";
import * as R from "./relay.mjs";
import * as R2 from "./round2.mjs";
import { createHash } from "node:crypto";

const root = join(dirname(fileURLToPath(import.meta.url)), "../../../..");
const read = (p) => readFileSync(join(root, p), "utf8");
const buildLog = read("docs/v2/BUILD-LOG.md");
const memory = read("docs/v2/v2-memory.jsonl");
const memRows = memory.trim().split("\n");
const memJson = JSON.stringify(JSON.parse(memRows[0]), null, 2);
const fixture = "Describe the studio wall in one line.";
const tok = countTokens;
const rows = [];
const add = (n, name, metric, before, after, lowerIsBetter = true) => rows.push({ n, name, metric, before, after, lowerIsBetter });

export async function runBench() {
  rows.length = 0;
  // Token lab. "before" is today's compressPrompt (whitespace fold), the existing V2 pass.
  const logTwice = memRows.slice(0, 40).join("\n") + "\n" + memRows.slice(0, 40).join("\n");
  add(1, "dedupe-lines", "tokens (memory rows sent twice)", tok(compressPrompt(logTwice)), tok(T.dedupeLines(logTwice)));
  const ask = "Please could you kindly review the board. I would like you to just check every lane in order to find the blocker. It is important to note that basically nothing merges without the gate.";
  add(2, "cut-filler", "tokens (polite task ask)", tok(compressPrompt(ask)), tok(compressPrompt(T.cutFiller(ask))));
  add(3, "compact-json", "tokens (pretty JSON memory row)", tok(memJson), tok(T.compactJson(memJson)));
  add(4, "ref-legend", "tokens (BUILD-LOG with repeated URLs/SHAs)", tok(buildLog), tok(T.refLegend(buildLog)));
  // 5/6 prompt cache over a 100-task mix with 20 distinct asks, repeats vary in case/space.
  const asks = Array.from({ length: 100 }, (_, i) => { const b = `summarize lane ${i % 20} status`; return i % 3 === 0 ? b.toUpperCase() : i % 3 === 1 ? `  ${b}  ` : b; });
  const model = async () => "ok";
  let calls = 0; for (const a of asks) { calls++; await model(a); }
  const exact = T.createPromptCache({ normalize: false }); for (const a of asks) await exact.get(a, model);
  add(5, "exact-prompt-cache", "model calls per 100 tasks", calls, exact.stats().misses);
  const norm = T.createPromptCache({ normalize: true }); for (const a of asks) await norm.get(a, model);
  add(6, "normalized-cache-key", "model calls per 100 tasks", exact.stats().misses, norm.stats().misses);
  add(7, "fit-budget", "max context tokens (budget 512, memory file)", tok(compressPrompt(memory)), tok(T.fitBudget(memory, 512)));
  // 8 routing: 50 tasks, 40 short "answer" asks, 10 long plans.
  const tasks = [...Array.from({ length: 40 }, () => ({ kind: "answer", prompt: memRows[1].slice(0, 400) })), ...Array.from({ length: 10 }, () => ({ kind: "plan", prompt: buildLog }))];
  const cost = (fn) => tasks.reduce((s, t) => s + T.computeUnits(fn(t), tok(t.prompt)), 0);
  add(8, "route-by-size", "compute units per 50 tasks", +cost(routeModel).toFixed(2), +cost((t) => T.routeBySize(t)).toFixed(2));
  // 9 summary repeat: 10 calls, summary grows by one line each time.
  const old = createSummaryCache(), neu = T.createDiffCache();
  let a = 0, b = 0, s = "";
  for (let i = 0; i < 10; i++) { s += memRows[i].slice(0, 120) + "\n"; a += old.context("p", memory, s).tokens; b += neu.context("p", memory, s).tokens; }
  add(9, "diff-only-summary", "tokens over 10 repeat calls", a, b);
