        method: req.method,
        url: req.url,
        raw,
        form: new URLSearchParams(String(req.headers["content-type"] ?? "").includes("json") ? "" : raw),
        contentType: req.headers["content-type"] ?? "",
        session: readSession(req.headers.cookie) || null,
        headers: req.headers,
      });
