import { readFileSync } from "node:fs";
import { loadGraph, hebbian, decay, predict, coMentionEpisodes } from "./artifacts/v2/src/brain/synapse.mjs";
const memory = readFileSync("docs/v2/v2-memory.jsonl","utf8");
const g = loadGraph(memory);
for (const e of coMentionEpisodes(g)) hebbian(g, e);
decay(g, { factor: 0.95, floor: 0.05 });
const seeds = [...g.nodes.keys()];
let chars = 0;
for (const n of seeds) chars += (g.nodes.get(n).text||"").length;
console.log({nodes: seeds.length, chars, avg: chars/seeds.length});

const toks = (s) => new Set(String(s ?? "").split(/[^a-z0-9]+/).filter((w) => w.length > 3));
const key = (a, b) => (a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`);
function adjacency(g) {
  const adj = new Map(); const push = (a, b, w) => { if (!adj.has(a)) adj.set(a, []); adj.get(a).push([b, w]); };
  for (const [k, w] of g.edges) { const [a, b] = k.split("\u0000"); push(a, b, w); push(b, a, w); }
  return adj;
}
const tokCache = new WeakMap();
function tokenSet(node) {
  if (!node) return new Set();
  const hit = tokCache.get(node);
  if (hit && hit.text === node.text) return hit.set;
  const set = toks(node.text);
  tokCache.set(node, { text: node.text, set });
  return set;
}
const adjCache = new WeakMap();
function adjacencyCached(g) {
  let sum = 0; for (const w of g.edges.values()) sum += w;
  const hit = adjCache.get(g);
  if (hit && hit.size === g.edges.size && hit.sum === sum && hit.edges === g.edges) return hit.adj;
  const adj = adjacency(g);
  adjCache.set(g, { size: g.edges.size, sum, edges: g.edges, adj });
  return adj;
}

function predictFast(g, seed, k = 5, { synW = 2, textW = 1 } = {}) {
  const adj = adjacencyCached(g); const nb = new Map(adj.get(seed) ?? []);
  const degW = new Map();
  for (const [n, list] of adj) degW.set(n, 1 / Math.log(1 + list.length));
  const T = tokenSet(g.nodes.get(seed)); const out = [];
  for (const n of g.nodes.keys()) {
    if (n === seed || nb.has(n)) continue;
    let s = 0; for (const [m] of adj.get(n) ?? []) if (nb.has(m)) s += degW.get(m);
    s += synW * (g.syn.get(key(seed, n)) ?? 0);
    if (textW) { const U = tokenSet(g.nodes.get(n)); let i = 0; for (const w of T) if (U.has(w)) i++; s += textW * (i / ((T.size + U.size - i) || 1)); }
    if (s > 0) out.push([n, s]);
  }
  return out.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, k).map(([n]) => n);
}

// correctness
let mismatch = 0;
for (const seed of seeds) {
  const a = predict(g, seed, 5).join("|");
  const b = predictFast(g, seed, 5).join("|");
  if (a !== b) mismatch++;
}
console.log({mismatch});

function bench(fn) {
  for (let i = 0; i < 20; i++) fn(i);
